        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>BETH-HORON</strong> house of the hollow, or of the cavern, the name of two towns or villages (2 Chronicles 8:5; 1 Chronicles 7:24) in the territory of Ephraim, on the way from Jerusalem to Joppa. They are distinguished as Beth-horon “the upper” and Beth-horon “the nether.” They are about 2 miles apart, the former being about 10 miles north-west of Jerusalem. Between the two places was the ascent and descent of Beth-horon, leading from Gibeon down to the western plain (Joshua 10:10, 11; 18:13,… <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
