        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>MICHAIAH</strong> (1.) The queen-mother of King Abijah (2 Chronicles 13:2). (See MAACAH [4]). (2.) One of those sent out by Jehoshaphat to instruct the people in the law (2 Chronicles 17:7). (3.) 2 Kings 22:12. (4.) The son of Gemariah. He reported to the king’s officers Jeremiah’s prediction, which he had heard Baruch read (Jeremiah 36:11, 13) from his father Gemariah’s chamber in the temple. (5.) A Levite (Nehemiah 12:35). (6.) A priest (Nehemiah 12:41). <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
