        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>BAASHA</strong> bravery, the third king of the separate kingdom of Israel, and founder of its second dynasty (1 Kings 15; 16; 2 Chronicles 16:1-6). He was the son of Ahijah of the tribe of Issachar. The city of Tirzah he made the capital of his kingdom, and there he was buried, after an eventful reign of twenty-four years (1 Kings 15:33). On account of his idolatries his family was exterminated, according to the word of the prophet Jehu (1 Kings 16:3, 4, 10-13). <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
