        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>JERUEL</strong> founded by God, a “desert” on the ascent from the valley of the Dead Sea towards Jerusalem. It lay beyond the wilderness of Tekoa, in the direction of Engedi (2 Chronicles 20:16, 20). It corresponds with the tract of country now called el-Hasasah. <em>[Reviewer: condense Easton's entry as needed.]</em>",
