        "<strong>Dictionary (Easton's).</strong> <strong>JEHOAHAZ J</strong> ehovah his sustainer, or he whom Jehovah holdeth. (1.) The youngest son of Jehoram, king of Judah (2 Chronicles 21:17; 22:1, 6, 8, 9); usually Ahaziah (q.v.). (2.) The son and successor of Jehu, king of Israel (2 Kings 10:35). He reigned seventeen years, and followed the evil ways of the house of Jeroboam. The Syrians, under Hazael and Benhadad, prevailed over him, but were at length driven out of the land by his son Jehoash (13:1-9, 25). (3.) Josiah’s third son, usually… <em>[Reviewer: condense Easton's entry as needed.]</em>",
