        "<strong>Dictionary (Easton's).</strong> <strong>TIGLATH-PILESER III</strong> . or Tilgath-Pil-neser, the Assyrian throne-name of Pul (q.v.). He appears in the Assyrian records as gaining, in the fifth year of his reign (about B.C. 741), a victory over Azariah (= Uzziah in 2 Chr.26:1), king of Judah, whose achievements are described in 2 Chronicles 26:6-15. He is first mentioned in Scripture, however, as gaining a victory over Pekah, king of Israel, and Rezin of Damascus, who were confederates. He put Rezin to death, and punished Pekah by taking a… <em>[Reviewer: condense Easton's entry as needed.]</em>",
