        "<strong>Dictionary (Easton's).</strong> <strong>COAT OF MAIL</strong> the rendering of a Hebrew word meaning “glittering” (1 Samuel 17:5, 38). The same word in the plural form is translated “habergeons” in 2 Chronicles 26:14 and Nehemiah 4:16. The “harness” (1 Kings 22:34), “breastplate” (Isaiah 59:17), and “brigandine” (Jeremiah 46:4), were probably also corselets or coats of mail. (See ARMOUR.) <em>[Reviewer: condense Easton's entry as needed.]</em>",
