        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>GEHENNA</strong> (originally Ge bene Hinnom; i.e., “the valley of the sons of Hinnom”), a deep, narrow glen to the south of Jerusalem, where the idolatrous Jews offered their children in sacrifice to Molech (2 Chronicles 28:3; 33:6; Jeremiah 7:31; 19:2-6). This valley afterwards became the common receptacle for all the refuse of the city. Here the dead bodies of animals and of criminals, and all kinds of filth, were cast and consumed by fire kept always burning. It thus in process of time… <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
