        "",
        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>HADAD-RIMMON</strong> (composed of the names of two Syrian idols), the name of a place in the valley of Megiddo. It is alluded to by the prophet Zechariah (12:11) in a proverbial expression derived from the lamentation for Josiah, who was mortally wounded near this place (2 Chronicles 35:22-25). It has been identified with the modern Rummaneh, a village “at the foot of the Megiddo hills, in a notch or valley about an hour and a half south of Tell Metzellim.” <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
