        "<strong>Dictionary (Easton's).</strong> <strong>JEHOIACHIN</strong> succeeded his father Jehoiakin (B.C. 599) when only eight years of age, and reigned for one hundred days (2 Chronicles 36:9). He is also called Jeconiah (Jeremiah 24:1; 27:20, etc.), and Coniah (22:24; 37:1). He was succeeded by his uncle, Mattaniah = Zedekiah (q.v.). He was the last direct heir to the Jewish crown. He was carried captive to Babylon by Nebuchadnezzar, along with the flower of the nobility, all the leading men in Jerusalem, and a great body of the general… <em>[Reviewer: condense Easton's entry as needed.]</em>",
