        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>DANIEL</strong> , BOOK OF is ranked by the Jews in that division of their Bible called the Hagiographa (Hebrews Khethubim). (See BIBLE.) It consists of two distinct parts. The first part, consisting of the first six chapters, is chiefly historical; and the second part, consisting of the remaining six chapters, is chiefly prophetical. The historical part of the book treats of the period of the Captivity. Daniel is “the historian of the Captivity, the writer who alone furnishes any series of… <em>[Reviewer: condense Easton's entry as needed.]</em>",
